import{_ as a,C as i,c as l,o as d,a3 as r,G as o,j as n,a as s}from"./chunks/framework.Dokpd4od.js";const T=JSON.parse('{"title":"Quotations","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/purchase/orders/quotations.md","filePath":"master/supply-chain/purchase/orders/quotations.md","lastUpdated":1793074831000}'),g={name:"master/supply-chain/purchase/orders/quotations.md"};function c(h,t,u,m,p,_){const e=i("ImagePopup");return d(),l("div",null,[t[0]||(t[0]=r('<h1 id="quotations" tabindex="-1">Quotations <a class="header-anchor" href="#quotations" aria-label="Permalink to &quot;Quotations&quot;">​</a></h1><p>A request for quotation (RFQ) asks a vendor for a price on products you want to buy. You build it, send it by email and, when the vendor agrees, confirm it. The RFQ then becomes a purchase order.</p><blockquote><p><strong>In simple words:</strong> An RFQ is a draft purchase. Nobody is committed until you click <strong>Confirm Order</strong>.</p></blockquote><p>Open <code>Purchase → Orders → Request for Quotation</code>. The page title is <strong>Request For Quotations</strong>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Some fields appear only when a setting is on. Set them in <code>Purchase → Settings → Manage Orders</code> or <code>Manage Products</code>.</p><table tabindex="0"><thead><tr><th>Field or column</th><th>Setting that shows it</th></tr></thead><tbody><tr><td><strong>Agreement</strong></td><td><strong>Purchase Agreements</strong></td></tr><tr><td><strong>Unit</strong></td><td><strong>Unit of Measure</strong></td></tr><tr><td><strong>Packaging Qty</strong> and <strong>Packaging</strong></td><td><strong>Packagings</strong></td></tr><tr><td><strong>Deliver To</strong></td><td>The Inventory app is installed</td></tr></tbody></table><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list shows every order that is not yet hidden by a tab.</p>',9)),o(e,{src:"/images1/purchase/rfq_list.png",alt:"Request For Quotations list with tabs and the New RFQ button"}),t[1]||(t[1]=r('<ul><li><strong>Tabs:</strong> <strong>Default</strong>, <strong>My Purchases</strong> (your own orders), <strong>Purchase Orders</strong> (confirmed ones) and <strong>Starred</strong>.</li><li><strong>Group by:</strong> <strong>Vendor</strong>, <strong>Buyer</strong>, <strong>State</strong>, <strong>Created At</strong>, <strong>Updated At</strong>.</li><li><strong>Search:</strong> type a reference or vendor name.</li><li><strong>Favorite star:</strong> click the star in the first column to mark an order. The <strong>Starred</strong> tab lists them.</li><li><strong>Columns:</strong> <strong>Reference</strong>, <strong>Vendor</strong>, <strong>Company</strong>, <strong>Buyer</strong>, <strong>Order Deadline</strong>, <strong>Source Document</strong>, <strong>Untaxed Amount</strong>, <strong>Total Amount</strong>, <strong>Status</strong>. You can also show <strong>Vendor Reference</strong>, <strong>Billing Status</strong> and <strong>Receipt Status</strong>.</li></ul><h2 id="create-an-rfq" tabindex="-1">Create an RFQ <a class="header-anchor" href="#create-an-rfq" aria-label="Permalink to &quot;Create an RFQ&quot;">​</a></h2><p>Scenario: you need 20 <strong>SSD 512GB</strong> from <strong>FreshFoods Wholesale</strong>.</p><ol><li>Click <strong>New RFQ</strong>.</li><li>Fill the <strong>General</strong> section.</li></ol>',4)),o(e,{src:"/images1/purchase/rfq_create_general.png",alt:"New RFQ form General section filled with vendor FreshFoods Wholesale, vendor reference, expected arrival and the agreement BO/1"}),t[2]||(t[2]=r('<ul><li><strong><em>Vendor:</em></strong> Required. Pick the supplier. Create one in <a href="./../../../getting-started/contacts/contacts.html">Contacts</a> first if needed.</li><li><strong><em>Vendor Reference:</em></strong> The vendor&#39;s own quote or order number. It helps match their delivery note.</li><li><strong><em>Agreement:</em></strong> Link a blanket order or template. Shown only with <strong>Purchase Agreements</strong> on.</li><li><strong><em>Currency:</em></strong> Required. It defaults to your company currency.</li><li><strong><em>Confirmation Date:</em></strong> Aureus fills it in when you click <strong>Confirm Order</strong>.</li><li><strong><em>Order Deadline:</em></strong> Required. The last day the vendor can accept.</li><li><strong><em>Expected Arrival:</em></strong> The date you want the goods.</li><li><strong><em>Deliver To:</em></strong> Required with Inventory. The warehouse receipt type that receives the goods, such as <strong>My Company: Receipts</strong>. Keep the default for one warehouse.</li></ul><ol start="3"><li>Open the <strong>Products</strong> tab and click <strong>Add Product</strong>.</li></ol>',2)),o(e,{src:"/images1/purchase/rfq_create_lines.png",alt:"Products tab with SSD 512GB line, quantity 20 and unit price 3300 filled"}),t[3]||(t[3]=r('<p>Each line has these columns:</p><ul><li><strong><em>Product:</em></strong> Required. Pick the item.</li><li><strong>Expected Arrival:</strong> The date for this line.</li><li><strong><em>Quantity:</em></strong> How many you want.</li><li><strong>Received</strong> and <strong>Billed:</strong> Appear after you confirm. They fill themselves.</li><li><strong>Unit:</strong> The unit of measure. Needs <strong>Unit of Measure</strong>.</li><li><strong>Packaging Qty</strong> and <strong>Packaging:</strong> Need <strong>Packagings</strong>.</li><li><strong>Taxes:</strong> The tax on the line.</li><li><strong>Discount (%):</strong> A percentage off the price.</li><li><strong>Unit Price:</strong> The price for one unit. A <a href="./../products/vendor-price-lists.html">vendor price</a> fills it when one matches.</li><li><strong>Amount:</strong> Calculated for you.</li></ul><p>Use <strong>Add Section</strong> to add a heading line and <strong>Add Note</strong> to add a text line between products. The summary below shows <strong>Untaxed Amount</strong>, <strong>Tax</strong> and <strong>Total Amount</strong>.</p><ol start="4"><li>Open <strong>Additional Information</strong> if needed.</li></ol>',4)),o(e,{src:"/images1/purchase/rfq_create_additional.png",alt:"Additional Information tab with buyer, company, source document, incoterm, incoterm location and payment term filled"}),t[4]||(t[4]=r('<ul><li><strong>Buyer:</strong> The person in charge.</li><li><strong>Company:</strong> The buying company.</li><li><strong>Source Document:</strong> Your own origin reference.</li><li><strong>Incoterm</strong> and <strong>Incoterm Location:</strong> The delivery terms.</li><li><strong>Payment Term:</strong> When you pay.</li></ul><ol start="5"><li>Open <strong>Terms and Conditions</strong> to write terms for the vendor.</li><li>Click <strong>Create</strong>. The order gets a number such as <strong>PO/00012</strong> and the status <strong>RFQ</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Click <strong>Create &amp; create another</strong> to enter several RFQs in a row.</p></div><h2 id="send-the-rfq" tabindex="-1">Send the RFQ <a class="header-anchor" href="#send-the-rfq" aria-label="Permalink to &quot;Send the RFQ&quot;">​</a></h2><ol><li>Open the RFQ and click <strong>Send By Email</strong>.</li><li>Check the window.</li></ol>',5)),o(e,{src:"/images1/purchase/rfq_send_email.png",alt:"Re-Send By Email window for PO/00016 with vendor, subject, message and the attached PDF"}),t[5]||(t[5]=r('<ul><li><strong>To:</strong> The vendors. They need an email address.</li><li><strong>Subject:</strong> The default is <strong>Purchase Order #name</strong>.</li><li><strong>Message:</strong> The email text. It includes <strong>Accept</strong> and <strong>Decline</strong> links.</li></ul><ol start="3"><li>Click send. The PDF is attached, the status becomes <strong>RFQ Sent</strong> and the email is saved in the chatter.</li></ol><p>The button now reads <strong>Re-Send By Email</strong>. Use it to send again.</p><p>To give the vendor a paper copy, click <strong>Print RFQ</strong>. It downloads a PDF and also sets the status to <strong>RFQ Sent</strong>.</p><h2 id="vendor-answers" tabindex="-1">Vendor answers <a class="header-anchor" href="#vendor-answers" aria-label="Permalink to &quot;Vendor answers&quot;">​</a></h2><p>The vendor can answer in two ways.</p><ul><li><strong>Email link:</strong> The vendor clicks <strong>Accept</strong> or <strong>Decline</strong> in the email. A page shows <strong>Quotation Accepted</strong> or <strong>Quotation Declined</strong>.</li><li><strong>Vendor portal:</strong> The vendor signs in, opens the RFQ and clicks <strong>Accept</strong> or <strong>Decline</strong>. A message confirms the answer.</li></ul>',7)),o(e,{src:"/images1/purchase/vp_rfq_accept_decline.png",alt:"Vendor portal page for an RFQ with the Accept, Decline and Download/Print buttons"}),t[6]||(t[6]=n("p",null,[s("Either way, Aureus adds a comment to the order chatter, such as "),n("strong",null,"The RFQ has been acknowledged by vendor."),s(" The status does not change on its own.")],-1)),o(e,{src:"/images1/purchase/vp_chatter_accepted.png",alt:"Order chatter with the comment The RFQ has been acknowledged by vendor from the vendor"}),t[7]||(t[7]=r('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>The answer only records what the vendor said. You still click <strong>Confirm Order</strong> to buy. For portal setup and screens, see <a href="./vendor-portal.html">Vendor portal</a>.</p></div><h2 id="confirm-the-order" tabindex="-1">Confirm the order <a class="header-anchor" href="#confirm-the-order" aria-label="Permalink to &quot;Confirm the order&quot;">​</a></h2><p>Click <strong>Confirm Order</strong>. The RFQ becomes a purchase order, or <strong>To Approve</strong> when approval applies. See <a href="./purchase-orders.html">Purchase orders</a>.</p>',3)),o(e,{src:"/images1/purchase/rfq_confirm.png",alt:"RFQ Sent order PO/00016 with the Confirm Order button highlighted"}),t[8]||(t[8]=r('<h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Button</th><th>Shown in</th><th>Result</th></tr></thead><tbody><tr><td><strong>Send By Email</strong></td><td><strong>RFQ</strong></td><td>Emails the vendor. Status becomes <strong>RFQ Sent</strong>.</td></tr><tr><td><strong>Re-Send By Email</strong></td><td><strong>RFQ Sent</strong></td><td>Sends the email again.</td></tr><tr><td><strong>Print RFQ</strong></td><td><strong>RFQ</strong>, <strong>RFQ Sent</strong></td><td>Downloads the PDF. Status becomes <strong>RFQ Sent</strong>.</td></tr><tr><td><strong>Confirm Order</strong></td><td><strong>RFQ</strong>, <strong>RFQ Sent</strong></td><td>Makes it a purchase order.</td></tr><tr><td><strong>Cancel</strong></td><td><strong>RFQ</strong>, <strong>RFQ Sent</strong></td><td>Status becomes <strong>Canceled</strong>.</td></tr><tr><td><strong>Delete</strong></td><td><strong>RFQ</strong>, <strong>RFQ Sent</strong></td><td>Removes the order.</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Orders overview</a></li><li><a href="./purchase-orders.html">Purchase orders</a></li><li><a href="./vendor-portal.html">Vendor portal</a></li><li><a href="./../products/vendor-price-lists.html">Vendor price lists</a></li><li><a href="./../../../getting-started/contacts/contacts.html">Contacts</a></li></ul>',4))])}const S=a(g,[["render",c]]);export{T as __pageData,S as default};
